const enfermedadData=[{"disease":"Se cita la primera frase del artículo y en la reunión contestan con la última","characteristic":"Se leyó lo que da y no lo que condiciona","opts":["Se leyó lo que da y no lo que condiciona","El artículo estaba derogado","Era materia pétrea","Faltaba ratificación"]},{"disease":"Niegan una reunión invocando el orden público y no dicen qué hecho la hace contraria","characteristic":"Usan un concepto indeterminado sin llenarlo, y hay que pedirlo por escrito","opts":["Usan un concepto indeterminado sin llenarlo, y hay que pedirlo por escrito","El artículo 78 no existe","Hace falta un tratado","Es un problema de vigencia"]},{"disease":"La petición lleva meses sin respuesta y nadie sabe cuál era el plazo","characteristic":"El artículo 80 remite el plazo a la ley: hay que ir a buscar cuál","opts":["El artículo 80 remite el plazo a la ley: hay que ir a buscar cuál","El derecho de petición no existe","El plazo lo fija la Constitución","Se necesita abogado para pedir"]},{"disease":"Se pelea contra la excepción del artículo 96 creyendo que recorta un derecho","characteristic":"Esa excepción protege: favorece a quien podría ser sancionado","opts":["Esa excepción protege: favorece a quien podría ser sancionado","El artículo 96 está derogado","Es una remisión al vacío","Solo aplica a la administración"]},{"disease":"Un reglamento define «abuso» de una forma que deja fuera casi todo lo que se quiere decir","characteristic":"Quien llena el concepto indeterminado decide el alcance real del derecho","opts":["Quien llena el concepto indeterminado decide el alcance real del derecho","El reglamento no puede definir nada","El artículo 72 no admite reglamento","Es problema de eficacia"]},{"disease":"El artículo remite a una ley de desarrollo y esa ley no aparece por ninguna parte","characteristic":"Es una remisión al vacío: el derecho queda sin contenido exigible","opts":["Es una remisión al vacío: el derecho queda sin contenido exigible","El artículo se derogó solo","La remisión se cumple sola","Hace falta esperar la reforma"]}];
let enferIdx=0,enferDone=false;
function showEnfer(){enferDone=false;if(enferIdx>=enfermedadData.length){const el=document.getElementById('enferDisease');if(el)el.textContent='🎉 ¡Completado!';const opts=document.getElementById('enferOpts');if(opts)opts.innerHTML='';return;}const d=enfermedadData[enferIdx];const prog=document.getElementById('enferProg');if(prog)prog.textContent=`${enferIdx+1} de ${enfermedadData.length}`;const dis=document.getElementById('enferDisease');if(dis)dis.textContent=d.disease;const opts=document.getElementById('enferOpts');if(!opts)return;opts.innerHTML='';_shuffle([...d.opts]).forEach(opt=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=opt;b.onclick=()=>checkEnfer(opt,b,d);opts.appendChild(b);});const fbEl=document.getElementById('fbEnfer');if(fbEl)fbEl.classList.remove('show');}
function checkEnfer(opt,btn,d){if(enferDone)return;enferDone=true;document.querySelectorAll('#enferOpts .qz-opt').forEach(b=>{if(b.textContent===d.characteristic)b.classList.add('correct');else if(b===btn&&b.textContent!==d.characteristic)b.classList.add('wrong');});const isOk=opt===d.characteristic;if(isOk){fb('fbEnfer','¡Correcto! +3 XP',true);if(!xpTracker.wgt.has('enfer_'+enferIdx)){xpTracker.wgt.add('enfer_'+enferIdx);pts(3);}sfx('ok');}else{fb('fbEnfer','Correcto: '+d.characteristic,false);sfx('no');}setTimeout(()=>{enferIdx++;showEnfer();},1800);}
function resetEnfer(){sfx('click');enferIdx=0;showEnfer();}

