function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"M.E.T.A.S publica una crítica documentada al sistema de evaluación de la Secretaría. Un funcionario avisa de que eso «puede ser un abuso del derecho de expresión» y que hay responsabilidad."},{"txt":"La familia convoca a treinta madres y padres en un patio para presentar el proyecto. En la alcaldía les dicen que no, porque podría ser contrario al orden público."},{"txt":"Se presenta una petición a la dirección departamental pidiendo autorización para usar las fichas. Pasan cuatro meses sin respuesta y nadie sabe decir cuál era el plazo."},{"txt":"Un maestro quiere reclamar por una ficha reproducida sin crédito y le dicen que primero necesita un abogado para poder entrar a un tribunal."},{"txt":"Un centro anuncia que sancionará a quien use material «no aprobado», y la sanción no aparece en ninguna norma anterior."},{"txt":"Cambian el reglamento y una oficina quiere aplicarlo a un trámite de M.E.T.A.S que se presentó tres meses antes."},{"txt":"Se acusa al proyecto de haber incumplido un requisito, y le piden que demuestre que sí lo cumplió, sin decir en qué se basa la acusación."},{"txt":"Un acuerdo dice que el material educativo se usará «conforme al interés social», y nadie sabe decir quién define ese interés social ni con qué criterio."}];
const critCaseQuestions=["1. ¿Qué da el artículo que está en juego, y qué le viene detrás: condición, remisión o excepción?","2. ¿Hay algún concepto que el texto use y no defina? ¿Quién lo está llenando, y responde de ello?","3. ¿La coletilla recorta o protege? Nómbralo, porque cambia de bando la discusión.","4. ¿Qué pides por escrito, y qué guardas del intercambio?"];
const critCaseGuides=["Se separan las dos partes antes de discutir nada, porque casi todo el mundo cita la primera y decide la segunda. Qué da: el derecho tal como lo enuncia la primera frase. Qué le viene detrás: una condición que lo limita desde dentro, una remisión que manda el contenido a otra norma, o una excepción que saca un caso de la regla. Si no hay nada detrás, el artículo cierra y lo que dice es lo que hay, que es más raro de lo que parece y por eso conviene notarlo.","Orden público, buenas costumbres, abuso, interés social, moral. Son palabras que condicionan un derecho y que el texto no define, así que su contenido lo escribe quien las invoca. La pregunta no es filosófica: es quién, en este caso concreto, está diciendo que se aplica, con qué hecho, y si eso queda por escrito con su nombre y su cargo. Un concepto indeterminado invocado de palabra y sin hecho no es una motivación, es una respuesta sin fundamento.","No todas las coletillas quitan. La excepción del artículo 96 amplía a favor de quien podría ser sancionado, y el propio 72 responsabiliza también a quienes restrinjan o impidan la circulación de ideas, no solo a quien abusa. Nombrar si la coletilla recorta o protege cambia de bando la discusión entera: se pasa de defenderse a invocar. Quien aprende a ver coletillas y no aprende a distinguirlas acaba peleando contra la única que estaba de su lado.","Por escrito se pide lo mismo casi siempre: qué hecho concreto sostiene la decisión, en qué norma consta, y quién la firma con su cargo. Y del intercambio se guarda copia sellada de recibido con fecha, que además es lo que hace correr el plazo del artículo 80. Si de todo esto sale un concepto usado sin llenarlo o una remisión a una norma que no existe, eso se documenta en el Registro de Grietas antes de que se olvide."];

const critErrorBank=[{"txt":"\"El artículo dice que es libre, así que puedo publicar lo que quiera sin consecuencias\".","g1":"La primera parte es cierta: no hay censura previa, nadie puede impedirlo antes. La segunda no: el mismo artículo dice que son responsables ante la ley los que abusen de ese derecho.","g2":"La distinción práctica importa: la protección es contra el permiso previo, no contra la responsabilidad posterior. Se publica sin pedir permiso, y se responde de lo que se publica."},{"txt":"\"Nos negaron la reunión por orden público, así que no hay nada que hacer\".","g1":"Orden público es un concepto que el artículo no define, y quien lo invoca tiene que decir qué hecho concreto lo hace aplicable. Sin hecho, no hay motivación.","g2":"Lo que se hace es pedirlo por escrito y ofrecer por escrito las medidas que resolverían esa preocupación. Eso convierte una negativa cerrada en una negociación con constancia."},{"txt":"\"El artículo 80 dice pronta respuesta, así que tienen que contestar rápido\".","g1":"Dice pronta respuesta en el plazo legal. La prontitud es del texto constitucional, pero el plazo concreto lo fija una ley, y hay que ir a buscar cuál es.","g2":"Y ahí está la grieta: esa ley la tramita y la aplica la misma administración que debe responder. No hace falta mala fe para que funcione mal."},{"txt":"\"Toda coletilla es una trampa para quitarte el derecho\".","g1":"No. La del artículo 96 amplía a favor de quien podría ser sancionado, y parte del 72 protege contra quienes restrinjan o impidan la circulación de ideas.","g2":"Aprender a ver coletillas sin aprender a leerlas lleva a pelear contra la que estaba de tu lado, que es peor que no haberlas visto."},{"txt":"\"Me acusan, así que tengo que demostrar que no lo hice\".","g1":"El artículo 89 dice lo contrario: toda persona es inocente mientras no se haya declarado su responsabilidad por autoridad competente.","g2":"En la práctica esto se usa poco fuera de lo penal y sirve para mucho más: lo que se pide es que quien afirma diga en qué se basa, antes de ponerse uno a probar lo imposible."},{"txt":"\"Cambió el reglamento, así que ahora se aplica también a lo que presentamos antes\".","g1":"El artículo 96 dice que la ley no tiene efecto retroactivo, y la excepción es solo en materia penal cuando favorece.","g2":"Aplicar hacia atrás una regla nueva y más exigente es exactamente lo que ese artículo impide, y conviene decirlo por escrito y con su número."}];

const critDecisionBank=["Le avisan de que una publicación del proyecto «puede ser un abuso»: ¿se retira, se mantiene o se pregunta? ¿Qué se pregunta exactamente?","Niegan una reunión invocando el orden público: ¿se reprograma, se discute o se pide por escrito? ¿Y qué se ofrece a cambio?","La petición del artículo 80 lleva cuatro meses sin respuesta: ¿qué se busca primero y qué se presenta después?","Un centro anuncia una sanción que no consta en ninguna norma anterior: ¿qué artículo se cita y en qué momento?","Quieren aplicar un reglamento nuevo a un trámite presentado antes: ¿qué se contesta en una línea?","Un acuerdo remite al «interés social» sin decir quién lo define: ¿se firma, se pregunta o se propone otra redacción?","Le piden a la familia que demuestre que cumplió algo, sin decir en qué se basa la acusación: ¿qué se pide primero?","Un artículo de derechos remite a una ley que nunca se dictó: ¿qué se puede exigir mientras tanto y qué se apunta?"];
const critDecisionGuide='La decisión correcta en esta etapa sigue siempre el mismo orden: primero se nombra el dato que cruza la frontera y de dónde viene; después se escribe la comprobación como lista permitida y se pone del lado del servidor, que es el que el usuario no puede editar; después se decide qué pasa cuando la comprobación no se puede hacer, y ahí se falla cerrado, nunca en silencio; y al final se rompe la comprobación a propósito para ver que de verdad se pone roja. Si el fallo no se puede oír, todavía no está resuelto.';

const critCompareBank=[{"a":"Pedir por escrito qué hecho concreto hace aplicable el «orden público».","b":"Discutir en la oficina si la reunión es o no contraria al orden público.","ga":"Caso A: obliga a llenar el concepto con un hecho, que es lo que casi nunca hay, y deja constancia con nombre y cargo.","gb":"Caso B: convierte un problema de motivación en una discusión de opiniones, donde gana quien tiene la firma."},{"a":"Leer el artículo entero antes de citarlo en la reunión.","b":"Citar la primera frase, que es la que todos recuerdan.","ga":"Caso A: se llega sabiendo qué le van a contestar, porque la respuesta suele estar en la última línea del mismo artículo.","gb":"Caso B: se cita algo cierto y a medias, y basta con que el otro lea la coletilla para que se caiga el argumento entero."},{"a":"Entregar la petición por duplicado y exigir sello de recibido con fecha.","b":"Entregarla y confiar en que quedó registrada.","ga":"Caso A: el plazo del artículo 80 empieza a correr desde ese sello, y hay con qué demostrarlo.","gb":"Caso B: sin constancia no hay fecha, y sin fecha no hay plazo que reclamar por mucho que la Constitución prometa prontitud."},{"a":"Nombrar si la coletilla recorta o protege antes de decidir la estrategia.","b":"Tratar toda coletilla como un recorte y atacarla.","ga":"Caso A: cuando protege, se invoca en vez de pelearla, y eso cambia de bando la discusión entera.","gb":"Caso B: se gasta esfuerzo en tumbar la excepción del 96, que era justamente la que estaba a favor."}];

const critCauseBank=[{"cause":"Se cita solo la primera frase de un artículo de derechos.","guide":"En la reunión contestan con la última y el argumento se cae entero, incluida la parte que sí era correcta. Se pierde el punto y la credibilidad de lo que venía después."},{"cause":"Se acepta una negativa fundada en «orden público» sin pedir el hecho concreto.","guide":"Queda el precedente de que aquí basta invocar la palabra, y la próxima vez se invocará antes y con menos explicación."},{"cause":"Se entrega una petición sin exigir sello de recibido.","guide":"El plazo del artículo 80 nunca empieza a correr de forma demostrable, y a los cuatro meses no hay ni respuesta ni forma de reclamarla."},{"cause":"Se pelea contra la excepción del artículo 96 creyendo que recorta.","guide":"Se gasta el esfuerzo en tumbar la coletilla que estaba a favor, y de paso se le enseña al otro un argumento que no había visto."},{"cause":"Se firma un acuerdo que remite al «interés social» sin decir quién lo define.","guide":"El alcance de lo firmado lo escribirá después quien invoque esa palabra, y no será la casa."},{"cause":"Se acepta la carga de demostrar que se cumplió algo, sin que digan en qué se basa la acusación.","guide":"Se entra a probar lo imposible mientras el que acusa no sostiene nada, cuando el artículo 89 pone la inocencia como punto de partida."}];
const critEffectBank=[{"effect":"La publicación se mantuvo y nadie volvió a hablar de abuso.","guide":"Se contestó que el artículo 72 prohíbe la censura previa y que la responsabilidad posterior exige decir qué hecho concreto constituye el abuso. Eso no se contestó nunca."},{"effect":"La reunión se hizo, y con la negativa por escrito guardada.","guide":"Se pidió el hecho concreto que la hacía contraria al orden público y se ofrecieron por escrito medidas para resolverlo. La negativa no se sostuvo."},{"effect":"La petición se resolvió, y el plazo se pudo contar desde una fecha cierta.","guide":"Se entregó por duplicado, con sello de recibido, nombre y cargo. Sin eso el artículo 80 promete prontitud sobre nada."},{"effect":"El reglamento nuevo no se aplicó al trámite anterior.","guide":"Se citó el artículo 96 con su número: la ley no tiene efecto retroactivo, y la excepción es solo penal y solo cuando favorece."},{"effect":"Quien acusaba tuvo que decir en qué se basaba.","guide":"Se invocó el artículo 89 antes de ponerse a probar nada. La inocencia es el punto de partida, no el premio final."},{"effect":"El acuerdo quedó firmado sin la frase «conforme al interés social».","guide":"Se pidió cambiarla por el hecho concreto que se quería asegurar. Lo que no se puede definir, no se firma."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 El derecho sobre la mesa · Forma ${cf} · Los derechos y la coletilla · Ruta de la Ley y sus Grietas`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. El derecho sobre la mesa <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Qué da el artículo y qué le viene detrás, hay alguna palabra que el texto no defina, y esa coletilla recorta o protege? Explica qué pides por escrito y qué guardas del intercambio.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuál de los dos deja al otro con la carga de decir en qué se basa? 2. ¿Por qué no son la misma decisión?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0 a 20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 El derecho sobre la mesa: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. El derecho sobre la mesa</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Qué da el artículo y qué le viene detrás, hay alguna palabra que el texto no defina, y esa coletilla recorta o protege? Explica qué pides por escrito y qué guardas del intercambio.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuál de los dos deja al otro con la carga de decir en qué se basa? 2. ¿Por qué no son la misma decisión?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>El derecho sobre la mesa Los derechos y la coletilla · Ruta de la Ley y sus Grietas · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · El derecho sobre la mesa · Los derechos y la coletilla · Ruta de la Ley y sus Grietas · Etapa 3 · Derecho y Ley</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: El derecho sobre la mesa · Los derechos y la coletilla · Ruta de la Ley y sus Grietas · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1","icon":"🎁","label":"Lo que da","text":"La primera frase: <strong>el derecho tal como se enuncia</strong>. <strong>Sirve para:</strong> saber de qué se está hablando. <strong>Engaña:</strong> porque es la que se cita y la que se recuerda, y casi nunca es la que decide."},{"y":"2","icon":"🎭","label":"La coletilla","text":"Lo que viene después y <strong>decide cuánto queda</strong>. <strong>Tres formas:</strong> condiciona, remite o exceptúa. <strong>Se pierde:</strong> leyendo solo hasta el primer punto."},{"y":"3","icon":"🔗","label":"La condición","text":"Limita el derecho <strong>desde dentro</strong>, sin mandarlo a otra parte. <strong>Se reconoce:</strong> «siempre que», «en tanto no». <strong>Aquí:</strong> el artículo 78 con el orden público y las buenas costumbres."},{"y":"4","icon":"➡️","label":"La remisión","text":"Manda el contenido real <strong>a otra norma</strong>. <strong>Se reconoce:</strong> «en el plazo legal», «en la forma que señalan las leyes». <strong>Aquí:</strong> los artículos 80 y 82, que reconocen y remiten en la misma frase."},{"y":"5","icon":"🚪","label":"La excepción","text":"Saca <strong>un caso concreto</strong> de la regla. <strong>Se reconoce:</strong> «salvo», «excepto». <strong>Ojo:</strong> no siempre recorta. La del artículo 96 protege a quien podría ser sancionado."},{"y":"6","icon":"❓","label":"El concepto indeterminado","text":"Una palabra que el artículo usa y <strong>no define</strong>: orden público, buenas costumbres, abuso, interés social. <strong>Lo llena:</strong> quien lo invoca. <strong>Por eso:</strong> se pide el hecho concreto, por escrito."},{"y":"7","icon":"🔒","label":"El artículo que cierra","text":"El que <strong>decide él mismo</strong> y no manda a nadie. <strong>Aquí:</strong> el 59, que declara inviolable la dignidad humana, y el 89, que declara inocente a toda persona. <strong>Sirve de contraste:</strong> así se ve lo que hace la coletilla en los demás."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(leyoEntero){sfx(leyoEntero?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(leyoEntero){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🔎</span><span class="ms-text"><strong>Leíste el artículo entero antes de la reunión:</strong> el derecho está en la primera frase y la responsabilidad por abuso, en la última. Llegaste sabiendo con qué te iban a contestar.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📝</span><span class="ms-text"><strong>Y pediste el hecho concreto:</strong> qué parte de lo publicado constituye el abuso, en qué norma consta y quién lo firma. Eso no se contestó, y la publicación se quedó donde estaba.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">📣</span><span class="ms-text"><strong>Citaste la primera frase:</strong> «es libre la emisión del pensamiento, sin previa censura». Sonó fuerte y era verdad.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🎭</span><span class="ms-text"><strong>Y te contestaron con la última:</strong> «son responsables ante la ley los que abusen de este derecho». Del mismo artículo. Se cayó el argumento entero, incluida la parte que sí era correcta.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"daquita":{"nombre":"Lo que da y lo que quita","icon":"🎭","estructura":{"title":"Qué es","info":"• <strong>Lo que da:</strong> el derecho, en la primera frase<br>• <strong>La coletilla:</strong> lo que viene después y decide cuánto queda<br>• Tres formas: condiciona, remite o exceptúa"},"funcion":{"title":"Cómo se reconoce","info":"• Se subraya con dos colores: <strong>lo que da</strong> y <strong>lo que condiciona</strong><br>• Se lee hasta el final del artículo, no hasta el primer punto<br>• Se pregunta: si me contestan con la última línea, ¿qué me queda?"},"enfermedades":{"title":"Dónde se cae","info":"• Citando la primera frase, que es la que todos recuerdan<br>• Creyendo que un derecho reconocido es un derecho absoluto<br>• Descubriendo la coletilla <strong>en la ventanilla</strong> y no antes"},"cuidados":{"title":"En este proyecto","info":"• Antes de invocar un derecho en una reunión, se lee <strong>entero</strong><br>• Se llega sabiendo con qué van a contestar<br>• Y lo que salga de esa lectura se apunta en el <strong>Registro de Grietas</strong>"}},"indeterminados":{"nombre":"Los conceptos que nadie define","icon":"❓","estructura":{"title":"Qué es","info":"• Palabras que condicionan un derecho y <strong>el texto no define</strong><br>• Orden público, buenas costumbres, abuso, interés social, moral<br>• Su contenido lo escribe <strong>quien las invoca</strong>"},"funcion":{"title":"Cómo se reconoce","info":"• Se pregunta: ¿esta palabra está definida en algún sitio?<br>• Y la pregunta que sirve de verdad: <strong>¿qué hecho concreto</strong> la hace aplicable aquí?<br>• Un concepto sin hecho no es motivación, es una respuesta sin fundamento"},"enfermedades":{"title":"Dónde se cae","info":"• Discutiendo la palabra en abstracto, que es la discusión que se pierde<br>• Aceptando la negativa de palabra, sin nombre ni cargo<br>• Sin ofrecer nada: una negativa cerrada es más fácil de sostener que una negociada"},"cuidados":{"title":"En este proyecto","info":"• Toda invocación de estas palabras se pide <strong>por escrito</strong><br>• Con el hecho concreto y con <strong>quién la firma</strong><br>• Y se ofrece por escrito qué resolvería esa preocupación"}},"proteger":{"nombre":"La coletilla que protege","icon":"🛡️","estructura":{"title":"Qué es","info":"• No todas recortan: algunas <strong>amplían a tu favor</strong><br>• <strong>Art. 96:</strong> la ley no es retroactiva, <strong>excepto</strong> en penal cuando favorece<br>• <strong>Art. 72:</strong> responden también quienes restrinjan o impidan la circulación de ideas"},"funcion":{"title":"Cómo se reconoce","info":"• Se pregunta <strong>a quién beneficia</strong> la excepción, no solo qué dice<br>• Si beneficia a quien podría ser sancionado, es de las que protegen<br>• Y entonces no se pelea: <strong>se invoca</strong>"},"enfermedades":{"title":"Dónde se cae","info":"• Tratando toda coletilla como un recorte, por costumbre<br>• Gastando el esfuerzo en tumbar la única que estaba a favor<br>• Y de paso enseñándole al otro un argumento que no había visto"},"cuidados":{"title":"En este proyecto","info":"• Antes de atacar una coletilla se nombra: <strong>¿recorta o protege?</strong><br>• El <strong>96</strong> sirve cuando quieren aplicar hacia atrás una regla nueva<br>• El <strong>89</strong> sirve cuando le piden a la casa probar lo imposible"}},"peticion":{"nombre":"La petición y su plazo","icon":"📨","estructura":{"title":"Qué es","info":"• <strong>Art. 80:</strong> derecho a presentar peticiones y a obtener <strong>pronta respuesta en el plazo legal</strong><br>• Reconoce y remite en la misma frase<br>• La prontitud es constitucional; el plazo lo fija una ley"},"funcion":{"title":"Cómo se reconoce","info":"• Se escribe con hechos numerados y <strong>una petición concreta</strong><br>• Se dirige a quien de verdad puede resolverla<br>• Se entrega <strong>por duplicado</strong> y se exige sello de recibido con fecha"},"enfermedades":{"title":"Dónde se cae","info":"• Entregando sin sello: sin fecha cierta <strong>no hay plazo</strong> que reclamar<br>• Pidiendo de palabra, que no deja rastro<br>• Escribiendo una queja en vez de una petición que se pueda cumplir"},"cuidados":{"title":"En este proyecto","info":"• De toda entrega se guarda <strong>copia sellada</strong> con nombre y cargo<br>• El plazo se cuenta desde ese sello, no desde la conversación<br>• Y la remisión del 80 va al Registro: es la grieta más limpia de la etapa"}}};
let labParte='daquita',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue estudiando tu sistema!','¡Muy buen trabajo!','¡Excelente gestor en formación!','¡Sabes por dónde se mueve esto!','¡Estratega institucional!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🎭 ¡'+name+' completó la Etapa 3 de la Ruta de la Ley y sus Grietas (Los derechos y la coletilla)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

